async function getJSON(e){const n=await fetch(e);if(!n.ok)throw new Error(`Failed request: ${e}`);return n.json()}function estimateReadTime(e){const n=(e||"").trim().split(/\s+/).filter(Boolean).length;return`${Math.max(1,Math.ceil(n/200))} min read`}function projectCard(e){return`\n    <article class="card">\n      <h3><a href="${e.url}" target="_blank" rel="noopener">${e.name}</a></h3>\n      <p>${e.description||"No description provided."}</p>\n      <div class="card-meta">\n        <span class="badge">Star ${e.stars}</span>\n        ${e.highlight?`<span class="badge">${e.highlight}</span>`:""}\n        <span class="badge status-live">${e.fallback?"Cached":"Live"}</span>\n      </div>\n    </article>\n  `}function blogCard(e){const n=(e.tags||[]).map(e=>`<span class="badge">${e}</span>`).join("");return`\n    <article class="card">\n      <h3>${e.title}</h3>\n      <p>${e.excerpt}</p>\n      <div class="card-meta">\n        <span class="badge">${e.date||"Undated"}</span>\n        <span class="badge">${estimateReadTime(e.excerpt)}</span>\n      </div>\n      <p class="card-meta">${n}</p>\n    </article>\n  `}function renderLoading(e,n){e.classList.add("loading"),e.innerHTML=Array.from({length:n},()=>'\n    <article class="card">\n      <h3>Loading...</h3>\n      <p>Fetching content...</p>\n    </article>\n  ').join("")}async function loadProjects(){const e=document.getElementById("projects-grid");renderLoading(e,3);try{const n=await getJSON("/api/showcase");e.classList.remove("loading"),e.innerHTML=n.repos.map(projectCard).join("")}catch(n){e.classList.remove("loading"),e.innerHTML='<article class="card"><p>Unable to load projects right now.</p></article>'}}async function loadBlog(){const e=document.getElementById("blog-grid");renderLoading(e,3);try{const n=await getJSON("/api/blog");e.classList.remove("loading"),e.innerHTML=n.posts.map(blogCard).join("")}catch(n){e.classList.remove("loading"),e.innerHTML='<article class="card"><p>Unable to load writings right now.</p></article>'}}function initMobileNav(){const e=document.querySelector(".menu-toggle"),n=document.getElementById("primary-nav");e&&n&&e.addEventListener("click",()=>{const a="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",String(!a)),n.classList.toggle("open")})}document.getElementById("year").textContent=(new Date).getFullYear(),initMobileNav(),loadProjects(),loadBlog();